INSERT INTO mail_template (code, language, subject, body, enabled, last_update) VALUES ( 'ONBOARDING', 'it', 'Benvenuto su QTM', 'Ciao ${firstName},

Il tuo account è stato creato correttamente.
Username: ${firstName}
Password temporanea: ${password}
Accedi qui: ${loginUrl}

Per motivi di sicurezza dovrai cambiare la password al primo login.

Cordiali saluti,
Il team QTM', true, CURRENT_TIMESTAMP ) AS new_values ON DUPLICATE KEY UPDATE subject = new_values.subject, body = new_values.body, enabled = new_values.enabled, last_update = CURRENT_TIMESTAMP;
INSERT INTO mail_template (code, language, subject, body, enabled, last_update) VALUES ( 'ONBOARDING', 'en', 'Welcome to QTM', 'Hi ${firstName},

Your account has been created successfully.
Username: ${firstName}
Temporary password: ${password}
Login here: ${loginUrl}

For security reasons, you will be required to change your password at first login.

Best regards,
The QTM Team', true, CURRENT_TIMESTAMP ) AS new_values ON DUPLICATE KEY UPDATE subject = new_values.subject, body = new_values.body, enabled = new_values.enabled, last_update = CURRENT_TIMESTAMP;
INSERT INTO mail_template (code, language, subject, body, enabled, last_update) VALUES ( 'PASSWORD_RECOVER', 'it', 'Recupero password QTM', 'Ciao ${firstName},

Abbiamo ricevuto una richiesta di reset password per il tuo account.
Apri questo link per impostare una nuova password:

${resetUrl}

Se non hai richiesto tu il reset, ignora questa mail.

Cordiali saluti,
Il team QTM', true, CURRENT_TIMESTAMP ) AS new_values ON DUPLICATE KEY UPDATE subject = new_values.subject, body = new_values.body, enabled = new_values.enabled, last_update = CURRENT_TIMESTAMP;
INSERT INTO mail_template (code, language, subject, body, enabled, last_update) VALUES ( 'PASSWORD_RECOVER', 'en', 'QTM Password Recovery', 'Hi ${firstName},

We received a password reset request for your account.
Open this link to set a new password:

${resetUrl}

If you did not request this, please ignore this email.

Best regards,
The QTM Team', true, CURRENT_TIMESTAMP ) AS new_values ON DUPLICATE KEY UPDATE subject = new_values.subject, body = new_values.body, enabled = new_values.enabled, last_update = CURRENT_TIMESTAMP;

